(function(){"use strict";document.querySelectorAll('.td-content input[type="checkbox"][disabled]').forEach(function(e){if(e.hasAttribute("aria-label")||e.hasAttribute("aria-labelledby"))return;var t=e.closest("li"),n=t?t.textContent.replace(/\s+/g," ").trim():"";n?e.setAttribute("aria-label",n):e.setAttribute("aria-hidden","true")}),document.querySelectorAll('.td-content i[class*="fa-"], .td-content span[class*="fa-"]').forEach(function(e){if(e.textContent.trim()||e.hasAttribute("aria-label")||e.hasAttribute("title"))return;e.setAttribute("aria-hidden","true")})})()